/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void eips_shutdown_func(void * arg)
{
  if(!eips_vars.speed_status && eips_vars.rpm_status)
    {      
      eips_alert_func        (0);   // alert the user but the timer stop because the shutdown timer not running
      
      eips_alert_timeout_stop() ;
      
      cmd_q_insert(INPUT_EIPS_SHUTDOWN, COMMAND_INSERT_TIMEOUT);

      eips_shutdown_check_timeout_start() ;

      #if DBG_EIPS == 1
        dbg_tx_text("\nEIPS Shutdown Done") ; 
      #endif
    }
  else
    {
      #if DBG_EIPS == 1
        dbg_tx_text("\nEIPS Shutdown Fail") ;
      #endif
    }
}

